import { Component, OnInit, ViewEncapsulation } from '@angular/core'
import { ActivatedRoute, Router } from '@angular/router'
import { CookieService } from 'ngx-cookie-service'
import { COOKIE_ROLE } from 'src/app/core/const/constants'
import { Roles } from 'src/app/core/enums/roles'
import { SideNavService } from 'src/app/core/services/util/side-nav.service'

@Component({
    selector: 'app-side-nav',
    templateUrl: './side-nav.component.html',
    styleUrls: ['./side-nav.component.scss'],
    encapsulation: ViewEncapsulation.Emulated,
})
export class SideNavComponent implements OnInit {
    private _isAdmin = false
    private _isDemo = false
    get isAdmin() {
        return this._isAdmin
    }
    get isDemo() {
        return this._isDemo
    }
    constructor(
        public sideNavService: SideNavService,
        public router: Router,
        private cookieService: CookieService
    ) {}

    ngOnInit(): void {
        let role = this.cookieService.get(COOKIE_ROLE)
        this._isAdmin = role === Roles.Administrator
        const domain = window.location.host
        let tenant = domain.split('.')[0].replace('-', '')
        this._isDemo =
            tenant == 'demo' ||
            tenant == 'divinaprovidencia' ||
            tenant == 'guadalupevolcanes' ||
            tenant == 'santuarioguadalupano_' ||
            tenant == 'localhost:4200'
    }
    navigateTo(route: string) {
        this.router.navigate([route])
    }
}
